import java.util.Random;

public class CompareRandomDemo {
    public static void main(String[] args) {
        StringBuilder sb1 = new StringBuilder();
        for (int i = 0; i < 10; i++) {
            int n = (int) (Math.random() * 50) + 1;   // Math.random 版本
            sb1.append(n >= 1 && n <= 50).append(' ');
        }
        System.out.println(sb1.toString().trim());

        Random r = new Random();
        StringBuilder sb2 = new StringBuilder();
        for (int i = 0; i < 10; i++) {
            int n = r.nextInt(50) + 1;                // Random 版本，简洁且无精度转换
            sb2.append(n >= 1 && n <= 50).append(' ');
        }
        System.out.println(sb2.toString().trim());
    }
}
